#!/usr/bin/env node
// pnpm email:disposable-update [commit] — regenerates the disposable e-mail domain list (BF-028) from
// github.com/disposable-email-domains/disposable-email-domains (CC0 1.0) at a pinned commit. Pass a newer commit
// (at least two weeks old, reviewed) to update; the commit is recorded in the generated file.
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const DEFAULT_COMMIT = '68e923683dc590073414ea25409333dfc0e0b245';
const commit = process.argv[2] ?? DEFAULT_COMMIT;
if (!/^[0-9a-f]{40}$/.test(commit)) {
  console.error('Usage: update-disposable-domains.mjs [40-hex commit]');
  process.exit(2);
}
const source = `https://raw.githubusercontent.com/disposable-email-domains/disposable-email-domains/${commit}/disposable_email_blocklist.conf`;
const target = join(
  dirname(fileURLToPath(import.meta.url)),
  '../apps/api/src/modules/business-graph/domain/value-objects/disposable-domains.data.ts',
);

const response = await fetch(source, { signal: AbortSignal.timeout(30_000) });
if (!response.ok) {
  console.error(`Download failed: HTTP ${response.status}`);
  process.exit(1);
}
const DOMAIN =
  /^(?=.{3,253}$)[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/;
const domains = [
  ...new Set(
    (await response.text())
      .split('\n')
      .map((line) => line.trim().toLowerCase())
      .filter((line) => DOMAIN.test(line)),
  ),
].sort();
if (domains.length < 1_000) {
  console.error(`Suspiciously short list (${domains.length} domains): not written.`);
  process.exit(1);
}

writeFileSync(
  target,
  [
    '// Generated by scripts/update-disposable-domains.mjs — do not edit by hand.',
    `// Source: disposable-email-domains/disposable-email-domains@${commit} (CC0 1.0).`,
    '/** Disposable (throw-away) e-mail domains, one per line, sorted. */',
    `export const DISPOSABLE_DOMAINS = \`${domains.join('\n')}\`;`,
    '',
  ].join('\n'),
);
console.log(`Wrote ${domains.length} domains from ${commit}.`);
